// Embeds a decoration's original SVG files into a plain TypeScript module,
// so the decoration needs no bundler setting for importing .svg files
// (works as-is in Vite, Next.js, webpack, esbuild, plain browsers).
//
// The .svg files stay the single source of truth and are never modified:
// their text is copied byte for byte, and a SHA-256 of each is recorded.
//
//   node scripts/embed-assets.mjs                 → all decorations
//   node scripts/embed-assets.mjs halloween-pumpkin
//   node scripts/embed-assets.mjs --check         → fail if a generated file is stale
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = new URL('..', import.meta.url).pathname;
const decorationsDir = join(root, 'src/decorations');
const args = process.argv.slice(2);
const check = args.includes('--check');
const only = args.filter((a) => !a.startsWith('--'));

/** "mini pumpkin" → miniPumpkin, "leaf_1" → leaf1, "bat_head" → batHead */
const toKey = (name) =>
  name
    .split(/[\s_-]+/)
    .map((part, i) => (i === 0 ? part : part.charAt(0).toUpperCase() + part.slice(1)))
    .join('');

export function generate(assetsDir) {
  const files = readdirSync(assetsDir).filter((f) => f.endsWith('.svg')).sort();
  const lines = [
    '// GENERATED by scripts/embed-assets.mjs from the original .svg files in this folder.',
    '// Do not edit by hand: change the .svg file and run `npm run build`.',
    '',
  ];
  const hashes = [];
  for (const file of files) {
    const bytes = readFileSync(join(assetsDir, file));
    const text = bytes.toString('utf8');
    const key = toKey(file.replace(/\.svg$/, ''));
    lines.push(`/** ${file} */`);
    lines.push(`export const ${key}: string = ${JSON.stringify(text)};`);
    hashes.push(`  ${JSON.stringify(file)}: '${createHash('sha256').update(bytes).digest('hex')}',`);
  }
  lines.push('', '/** SHA-256 of each original file, for integrity checks. */');
  lines.push('export const SOURCE_SHA256: Record<string, string> = {', ...hashes, '};', '');
  return lines.join('\n');
}

let stale = 0;
for (const id of readdirSync(decorationsDir)) {
  if (only.length && !only.includes(id)) continue;
  const assetsDir = join(decorationsDir, id, 'assets');
  if (!existsSync(assetsDir)) continue;
  const target = join(assetsDir, 'sources.generated.ts');
  const next = generate(assetsDir);
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (check) {
    if (current !== next) {
      console.error(`stale: ${target} (run npm run build)`);
      stale++;
    }
  } else if (current !== next) {
    writeFileSync(target, next);
    console.log(`embedded ${id}/assets → sources.generated.ts`);
  }
}
if (stale) process.exit(1);
